import{_ as o,a0 as n,w as s,s as p,ao as g,I as l,x as i,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 有问必答：如何改变libvirt VM镜像的默认位置 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何改变libvirt VM镜像的默认位置 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何改变libvirt VM镜像的默认位置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何改变libvirt VM镜像的默认位置 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images","title":"Linux 有问必答：如何改变libvirt VM镜像的默认位置","tag":"201411","desc":""},"relativePath":"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images.md","filePath":"[post].md"}'),m={name:"201411/20141014 Linux FAQs with Answers--How to change default location of libvirt VM images.md"};function d(u,t,f,c,b,v){const e=n("Link");return s(),p("div",null,[t[11]||(t[11]=g(`<h1 id="linux-有问必答-如何改变libvirt-vm镜像的默认位置" tabindex="-1">Linux 有问必答：如何改变libvirt VM镜像的默认位置 <a class="header-anchor" href="#linux-有问必答-如何改变libvirt-vm镜像的默认位置" aria-label="Permalink to “Linux 有问必答：如何改变libvirt VM镜像的默认位置”">​</a></h1><blockquote><p><strong>提问</strong>： 我使用libvirt和virt-manager在我的Linux系统上创建虚拟机。我注意到虚拟机镜像位于/var/lib/libvirt/images目录。有没有办法改变虚拟机镜像的默认路径？</p></blockquote><p><strong>libvirt</strong>和它的GUI前端<strong>virt-manager</strong>可以使用不同的虚拟机管理程序创建和管理VM，例如LVM和Xen。默认上所有的虚拟机镜像通过<strong>libvirt</strong>创建到/var/lib/libvirt/images目录。然而，这有时并不是我们希望的。比如/var/lib/libvirt/images此处的磁盘分区大小有限。或者你想要存储所有的虚拟机镜像到一个特定的用于管理的仓库中。</p><p>实际上，你可以非常容易地改变libvirt镜像的默认目录，或者称之为“存储池”。</p><p>有两种方法可以改变默认存储池。</p><h3 id="方法一-virt-manager-gui" tabindex="-1">方法一: Virt-Manager GUI <a class="header-anchor" href="#方法一-virt-manager-gui" aria-label="Permalink to “方法一: Virt-Manager GUI”">​</a></h3><p>如果你正在使用virt-manager GUI程序，改变默认存储池非常容易。</p><p>进入<strong>virt-manager</strong>的菜单GUI “编辑” -&gt; &quot;连接细节&quot;。</p><p><img src="https://farm4.staticflickr.com/3935/15433062592_0d89a8d132_o.png" alt=""></p><p>你可以看到如下所是的默认存储池。在窗口的左下角，点击叉形按钮，将会停止默认的存储池。存储池一旦停止后，点击右边的垃圾桶，将会删除存储池。<strong>注意这个动作不会删除池中的镜像。</strong></p><p>现在点击左边的加号增加一个新的存储池。</p><p><img src="https://farm6.staticflickr.com/5600/15246703330_26884c8258_b.jpg" alt=""></p><p>输入新的存储池的名字（比如：default），并且选择存储池的类型。本例中，因为我们只是改变存储池目录所以选择“文件系统目录”。</p><p><img src="https://farm4.staticflickr.com/3928/15433416355_1a2f9f85ab_b.jpg" alt=""></p><p>输入新的存储池路径（比如，/storage）。</p><p><img src="https://farm6.staticflickr.com/5599/15433062732_195fa6701b_b.jpg" alt=""></p><p>这时，新的存储池应该启动了，并且自动在你创建一个新的虚拟机的时候使用。</p><p><img src="https://farm4.staticflickr.com/3934/15430217721_b14c3a93fa_b.jpg" alt=""></p><h3 id="方法二-virsh-命令行" tabindex="-1">方法二: Virsh 命令行 <a class="header-anchor" href="#方法二-virsh-命令行" aria-label="Permalink to “方法二: Virsh 命令行”">​</a></h3><p>另外一个改变默认存储池目录的方法是使用来自<strong>libvirt</strong>包的<strong>virsh</strong> 命令行工具。</p><p>首先，运行下面的命令来导出默认存储池的XML定义。</p><pre><code> $ virsh pool-dumpxml default &gt; pool.xml 
</code></pre><p>用文本编辑器打开XML文件，并且改变<code>&lt;path&gt;</code>节点中的/var/lib/libvirt/images改成新的地址。</p><pre><code>&lt;pool type=&#39;dir&#39;&gt;
  &lt;name&gt;default&lt;/name&gt;
  &lt;uuid&gt;0ec0e393-28a2-e975-feec-0c7356f38d08&lt;/uuid&gt;
  &lt;capacity unit=&#39;bytes&#39;&gt;975762788352&lt;/capacity&gt;
  &lt;allocation unit=&#39;bytes&#39;&gt;530052247552&lt;/allocation&gt;
  &lt;available unit=&#39;bytes&#39;&gt;445710540800&lt;/available&gt;
  &lt;source&gt;
  &lt;/source&gt;
  &lt;target&gt;
    &lt;path&gt;/var/lib/libvirt/images&lt;/path&gt;
    &lt;permissions&gt;
      &lt;mode&gt;0711&lt;/mode&gt;
      &lt;owner&gt;-1&lt;/owner&gt;
      &lt;group&gt;-1&lt;/group&gt;
    &lt;/permissions&gt;
  &lt;/target&gt;
&lt;/pool&gt;
</code></pre><p>移除现在的默认池。</p><pre><code>$ virsh pool-destroy default 
</code></pre><hr><pre><code>Pool default destroyed
</code></pre><p>现在创建一个基于更新后的XML文件的新存储池。</p><pre><code>$ virsh pool-create pool.xml 
</code></pre><hr><pre><code>Pool default created from pool.xml
</code></pre><p>这时，默认池已经改变到新的地址了，并且可以使用了。</p><hr>`,34)),l("p",null,[t[1]||(t[1]=i("via: ",-1)),r(e,{href:"http://ask.xmodulo.com/change-default-location-libvirt-vm-images.html"},{default:a(()=>[...t[0]||(t[0]=[i("http://ask.xmodulo.com/change-default-location-libvirt-vm-images.html",-1)])]),_:1})]),l("p",null,[t[4]||(t[4]=i("译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[2]||(t[2]=[i("geekpi",-1)])]),_:1}),t[5]||(t[5]=i(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=i("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[i("LCTT",-1)])]),_:1}),t[9]||(t[9]=i(" 原创翻译，",-1)),r(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[i("Linux中国",-1)])]),_:1}),t[10]||(t[10]=i(" 荣誉推出",-1))])])}const L=o(m,[["render",d]]);export{_ as __pageData,L as default};
